cd scripts && awk -F',' '
BEGIN {
    won=0; lost=0; pending=0; total_revenue=0
}
NR>1 {
    amount=$5; region=$3; status=$7;
    gsub(/[[:space:]]/, "", status);
    deals[region]++;
    if (status=="won") {
        total_revenue += amount;
        rev[region] += amount;
        won++;
    } else if (status=="lost") {
        lost++;
    } else {
        pending++;
    }
}
END {
    total = won + lost + pending;
    win_rate = (total > 0) ? won / total * 100 : 0;
    printf "=============================================\n";
    printf "  Meridian Analytics — Q3 Sales Summary\n";
    printf "=============================================\n";
    printf "  Total deals worked : %d\n", total;
    printf "  Won                : %d\n", won;
    printf "  Lost               : %d\n", lost;
    printf "  Pending            : %d\n", pending;
    printf "  Win rate           : %.1f%%\n", win_rate;
    printf "  Total revenue (won): $%\047d\n", total_revenue;
    printf "\n";
    printf "  Revenue by region (won deals):\n";
    # Sort by revenue descending
    n = asorti(rev, sorted);
    # Bubble sort by revenue descending
    for (i=1; i<=n; i++) for (j=i+1; j<=n; j++) {
        if (rev[sorted[i]] < rev[sorted[j]]) {
            tmp=sorted[i]; sorted[i]=sorted[j]; sorted[j]=tmp;
        }
    }
    for (i=1; i<=n; i++) {
        r = sorted[i];
        printf "    %-8s $%10\047d  (%d deals total)\n", r, rev[r], deals[r];
    }
    printf "=============================================\n";
}
' ../data/sales_q3.csv 2>&1

node -e "
const fs = require('fs');
const lines = fs.readFileSync('data/sales_q3.csv','utf8').trim().split('\n');
const header = lines[0].split(',');
const rows = lines.slice(1).map(l => {
  const c = l.split(',');
  return { region: c[2], amount: parseFloat(c[4]), status: c[6].trim() };
});

let won=0, lost=0, pending=0, totalRevenue=0;
const dealsByRegion = {}, revByRegion = {};

for (const r of rows) {
  dealsByRegion[r.region] = (dealsByRegion[r.region]||0) + 1;
  if (r.status==='won') { won++; totalRevenue+=r.amount; revByRegion[r.region]=(revByRegion[r.region]||0)+r.amount; }
  else if (r.status==='lost') lost++;
  else pending++;
}

const total = won+lost+pending;
const winRate = total ? (won/total*100) : 0;
const fmt = n => n.toLocaleString('en-US',{maximumFractionDigits:0});

const out = [];
out.push('='.repeat(45));
out.push('  Meridian Analytics — Q3 Sales Summary');
out.push('='.repeat(45));
out.push('  Total deals worked : ' + total);
out.push('  Won                : ' + won);
out.push('  Lost               : ' + lost);
out.push('  Pending            : ' + pending);
out.push('  Win rate           : ' + winRate.toFixed(1) + '%');
out.push('  Total revenue (won): \$' + fmt(totalRevenue));
out.push('');
out.push('  Revenue by region (won deals):');

const sorted = Object.entries(revByRegion).sort((a,b)=>b[1]-a[1]);
for (const [region, rev] of sorted) {
  const rPad = region.padEnd(8);
  const revStr = ('\$' + fmt(rev)).padStart(11);
  out.push('    ' + rPad + revStr + '  (' + dealsByRegion[region] + ' deals total)');
}
out.push('='.repeat(45));
console.log(out.join('\n'));
" 2>&1
